                    content = f.read()
                # Look for __version__ = '...'
                for line in content.split('\n'):
                    line = line.strip()
                    if line.startswith('__version__'):
                        # Extract version string
                        parts = line.split('=', 1)
                        if len(parts) == 2:
                            version = parts[1].strip().strip("'\"")
                            return version
            # Look for _version.py
            version_file2 = os.path.join(sp, '_version.py')
            if os.path.exists(version_file2):
                with open(version_file2, 'r') as f:
                    content = f.read()
                for line in content.split('\n'):
                    line = line.strip()
                    if line.startswith('__version__'):
                        parts = line.split('=', 1)
                        if len(parts) == 2:
                            version = parts[1].strip().strip("'\"")
                            return version
            # Look for pkg_resources or version info
            # Try __init__.py
            init_file = os.path.join(sp, '__init__.py')
            if os.path.exists(init_file):
                with open(init_file, 'r') as f:
                    content = f.read()
                for line in content.split('\n'):
                    line = line.strip()
                    if line.startswith('__version__'):
                        parts = line.split('=', 1)
                        if len(parts) == 2:
                            version = parts[1].strip().strip("'\"")
                            return version

    # If we couldn't find it, try using importlib
    import importlib
    try:
        spec = importlib.util.find_spec('setuptools')
        if spec is not None:
            # Try to get version without importing
