# We need to find setuptools version without importing setuptools
# The original code prints: system setuptools <version>
# We need to find the setuptools version from the filesystem

def find_setuptools_version():
    # Look for setuptools in site-packages directories
    # Check sys.path for setuptools
    for path in sys.path:
        setuptools_path = os.path.join(path, 'setuptools')
        if os.path.exists(setuptools_path):
            # Look for _version.py or __init__.py with __version__
            version_file = os.path.join(setuptools_path, '_version.py')
            if os.path.exists(version_file):
                with open(version_file, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line.startswith('__version__ = '):
                            # Extract the version string
                            val = line[len('__version__ = '):].strip()
                            # Remove quotes
                            val = val.strip("'\"")
                            return val
                        elif line.startswith('__version__'):
                            # Could be a tuple or other format
                            continue

            # Try __init__.py
            init_file = os.path.join(setuptools_path, '__init__.py')
            if os.path.exists(init_file):
                with open(init_file, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line.startswith('__version__ = '):
                            val = line[len('__version__ = '):].strip()
                            val = val.strip("'\"")
                            return val

            # Try looking for dist-info or egg-info
            # Also check for a version file
            version_txt = os.path.join(setuptools_path, 'version.py')
            if os.path.exists(version_txt):
                with open(version_txt, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line.startswith('version = '):
                            val = line[len('version = '):].strip()
                            val = val.strip("'\"")
                            return val

    # Try to find setuptools distribution info
    for path in sys.path:
        # Look for setuptools-*.egg-info or setuptools-*.dist-info
        entries = os.listdir(path)
        for entry in entries:
            if entry.startswith('setuptools') and ('.egg-info' in entry or '.dist-info' in entry):
                info_path = os.path.join(path, entry)
                if os.path.isdir(info_path):
                    # Look for PKG-INFO or METADATA
                    for fname in ['PKG-INFO', 'METADATA']:
                        metadata_file = os.path.join(info_path, fname)
                        if os.path.exists(metadata_file):
                            with open(metadata_file, 'r') as f:
                                for line in f:
                                    if line.startswith('Version: '):
                                        return line[len('Version: '):].strip()

    return None

