import os, sys

def _readlocale():
    for f in ['/etc/default/locale', '/etc/locale.conf', '/etc/LANG', os.environ.get('LANG', '')]:
        if isinstance(f, str) and f and os.path.exists(f):
            try:
                with open(f) as fh:
                    for line in fh:
                        line = line.strip()
                        if line.startswith('LANG=') or line.startswith('LC_ALL='):
                            v = line.split('=', 1)[1].strip().strip('"').strip("'")
                            if v:
                                return v
            except Exception:
                pass
    for var in ('LC_ALL', 'LC_CTYPE', 'LANG'):
        v = os.environ.get(var, '')
        if v:
            return v
    return 'C'

