# CPython's random uses Mersenne Twister. We need to replicate:
# 1. random.seed(1)
# 2. random.randrange(0, 10, 2)

# Let's understand what randrange(0, 10, 2) does:
# step = 2, start = 0, stop = 10
# width = (10 - 0) // 2 = 5
# It calls randrange(5) then returns start + result * step
# randrange(5) calls randbelow(5)
# randbelow(5) uses getrandbits to generate a number in [0, 5)

# Mersenne Twister implementation for CPython:
class MT19937:
    def __init__(self, seed):
        self.mt = [0] * 624
        self.mti = 625
        self.init_genrand(seed)

    def init_genrand(self, seed):
        self.mt[0] = seed & 0xffffffff
        for i in range(1, 624):
            self.mt[i] = (1812433253 * (self.mt[i-1] ^ (self.mt[i-1] >> 30)) + i) & 0xffffffff
        self.mti = 624

    def generate(self):
        if self.mti >= 624:
            self.tempering()
        y = self.mt[self.mti]
        self.mti += 1
        # Tempering
        y ^= (y >> 11)
        y ^= (y << 7) & 0x9d2c5680
        y ^= (y << 15) & 0xefc60000
        y ^= (y >> 18)
        return y & 0xffffffff

    def tempering(self):
        for i in range(624):
            x = (self.mt[i] & 0x80000000) + (self.mt[(i + 1) % 624] & 0x7fffffff)
            self.mt[i] = self.mt[(i + 397) % 624] ^ (x >> 1)
            if x & 1:
                self.mt[i] ^= 0x9908b0df
        self.mti = 0

def randbelow_mt(mt, n):
    """Replicate random.randbelow(n) using the Mersenne Twister"""
    if n <= 0:
        raise ValueError
    getmask = n - 1
    if n & getmask == 0:
        return mt.generate() & getmask
    retval = mt.generate() % n
    if retval >= n:
        # Rejection sampling
        limit = (-n) % n  # 2**k - n where 2**k >= n
        while retval >= n:
            retval = mt.generate() % n
    return retval

def randrange_mt(mt, start, stop, step):
    """Replicate random.randrange(start, stop, step)"""
    if step == 0:
        raise ValueError("step must be non-zero")
    if stop is None:
        if start is None:
            raise TypeError("must supply both or neither")
        stop = start
        start = 0
    if step < 0:
        if stop < start:
            width = -((stop - start) // step)
        else:
            width = 0
    else:
        width = (stop - start) // step
    if width <= 0:
        raise ValueError
    i = randbelow_mt(mt, width)
    return start + i * step

