        stripped = line.lstrip(' ')
        indent = len(line) - len(stripped)
        if margin is None:
            margin = indent
        else:
            margin = min(margin, indent)
    if margin:
        return '\n'.join(lines[0] + [line[margin:] if line else '' for line in lines[1:]])
    return text

