    lines = text.splitlines()
    if not lines:
        return ''
    if len(lines) == 1:
        return lines[0] + (suffix if suffix else '')
    first, rest = lines[0], lines[1:]
    indented = [prefix + line + suffix for line in rest]
    result = '\n'.join([first] + indented)
    if indent:
        result = indent + result.replace('\n', '\n' + indent)
    return result

