def _shorten(text, width, placeholder='…', break_on_hyphens=True, break_long_words=True):
    if len(text) <= width:
        return text
    if width < len(placeholder) + 1:
        return text[:width]
    truncate_at = width - len(placeholder)
    if break_on_hyphens:
        truncate_at = text.rfind('-', 0, truncate_at)
        if truncate_at != -1:
            truncate_at += 1
    if truncate_at < 1:
        truncate_at = 1
    result = text[:truncate_at] + placeholder
    if not break_on_hyphens:
        truncate_at = text.rfind(' ', 0, truncate_at)
        if truncate_at != -1:
            result = text[:truncate_at] + placeholder
    if not break_long_words:
        truncate_at = text.rfind(' ', 0, truncate_at)
        if truncate_at != -1:
            result = text[:truncate_at] + placeholder
    return result

