    for line in lines:
        stripped = line.lstrip(" \t")
        if stripped or not line:
            # Compute the indent
            indent = line[:len(line) - len(stripped)] if stripped else line
            if line:
                indents.append(indent)
    if not indents:
        return text
    # Find the longest common prefix of all indents
    if not indents:
        return text
