import sys

def parse_args(argv):
    n = 1
    word = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--n":
            if i + 1 >= len(argv):
                raise SystemExit("error: --n requires a value")
            n = int(argv[i + 1])
            i += 2
        else:
            if word is None:
                word = arg
            else:
                raise SystemExit("error: unexpected argument")
            i += 1
    if word is None:
        raise SystemExit("error: word argument required")
    return word, n

