def match_and_sub(pattern, repl, text):
    import re as _re
    # First, try to compile with the pattern as-is
    try:
        compiled = _re.compile(pattern)
        return compiled.sub(repl, text)
    except Exception:
        pass

    # If named groups caused issues, replace them with numbered groups
    # This is a fallback for simple cases

    # Count the named groups and their order of appearance
    named_groups = {}
    counter = 1
    modified_pattern = pattern
    i = 0
    while i < len(modified_pattern):
        if modified_pattern[i] == '(' and i + 1 < len(modified_pattern) and modified_pattern[i+1] == '?':
            if i + 2 < len(modified_pattern) and modified_pattern[i+2] == 'P':
                if i + 3 < len(modified_pattern) and modified_pattern[i+3] == '<':
                    # Find the closing >
                    close_idx = modified_pattern.find('>', i)
                    if close_idx != -1:
                        name = modified_pattern[i+4:close_idx]
                        if name not in named_groups:
                            named_groups[name] = counter
                            counter += 1
                        # Replace (?P<name> with just (
                        modified_pattern = modified_pattern[:i] + '(' + modified_pattern[close_idx+1:]
                        # Don't advance i, because we shifted
                        continue
        i += 1

    # Also replace \g<name> in replacement with \number
    modified_repl = repl
    i = 0
    while i < len(modified_repl):
        if modified_repl[i] == '\\' and i + 1 < len(modified_repl) and modified_repl[i+1] == 'g':
            if i + 2 < len(modified_repl) and modified_repl[i+2] == '<':
                close_idx = modified_repl.find('>', i)
                if close_idx != -1:
                    name = modified_repl[i+3:close_idx]
                    if name in named_groups:
                        num = named_groups[name]
                        modified_repl = modified_repl[:i] + '\\' + str(num) + modified_repl[close_idx+1:]
                        i = i + 2 + len(str(num)) + 1
                        continue
        i += 1

    try:
        compiled = _re.compile(modified_pattern)
        return compiled.sub(modified_repl, text)
    except Exception as e:
        raise e

