def search(pattern, string):
    # Manually implement the regex (?P<k>\w+)=(?P<v>\d+)
    # Find the first position where a sequence of \w+ is followed by '=' and then \d+
    n = len(string)
    word_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    digit_chars = set('0123456789')

    for i in range(n):
        if string[i] in word_chars:
            # Find end of \w+
            j = i
            while j < n and string[j] in word_chars:
                j += 1
            # Check if next char is '='
            if j < n and string[j] == '=':
                # Find start of \d+
                k = j + 1
                if k < n and string[k] in digit_chars:
                    l = k
                    while l < n and string[l] in digit_chars:
                        l += 1
                    k_val = string[i:j]
                    v_val = string[k:l]
                    return (k_val, v_val, (k_val, v_val))
    return None

