import re

def only_set_order_differs(cp: str, mp: str) -> bool:
    """Check if two strings differ only in the order of elements within sets/sets-like literals."""
    def extract_elements(line: str):
        # Extract elements from a line, handling both {1, 2} and {'c', 'a', 'b'}
        # Remove whitespace
        line = line.strip()
        if not line:
            return None
        # Remove outer braces
        if line.startswith('{') and line.endswith('}'):
            inner = line[1:-1]
        else:
            inner = line
        if not inner.strip():
            return []
        # Split by comma, but need to be careful with quoted strings
        # For simplicity, split by comma and strip
        elements = []
        for part in inner.split(','):
            part = part.strip()
            if part:
                elements.append(part)
        return elements

    cp_lines = [line for line in cp.split('\n') if line.strip()]
    mp_lines = [line for line in mp.split('\n') if line.strip()]

    if len(cp_lines) != len(mp_lines):
        return False

    for c_line, m_line in zip(cp_lines, mp_lines):
        c_elements = extract_elements(c_line)
        m_elements = extract_elements(m_line)
        if c_elements is None or m_elements is None:
            return False
        if c_elements is None:
            if c_line.strip() != m_line.strip():
                return False
            continue
        if len(c_elements) != len(m_elements):
            return False
        if sorted(c_elements) != sorted(m_elements):
            return False

    return True

