        astrs = a.splitlines()
        bstrs = b.splitlines()
        parsed_a = []
        for s in astrs:
            s = s.strip()
            if not s:
                continue
            a_s = s.replace("'", '"')
            parsed_a.append(eval(a_s))
        parsed_b = []
        for s in bstrs:
            s = s.strip()
            if not s:
                continue
            b_s = s.replace("'", '"')
            parsed_b.append(eval(b_s))

        if len(parsed_a) != len(parsed_b):
            return False

        for x, y in zip(parsed_a, parsed_b):
            if isinstance(x, set) and isinstance(y, set):
                if x != y:
                    return False
                if list(x) != list(y):
                    return True
            elif x != y:
                return False
        return False

    else:
        if a == b:
            return False
        if isinstance(a, set) and isinstance(b, set):
            return True
        return False


