                        result.add(int(elem))
                    except:
                        result.add(elem)
            return frozenset(result)
        return frozenset()

    corpus_sets = [parse_set(line) for line in lines_corpus]
    model_sets = [parse_set(line) for line in lines_model]

    # Check if they contain the same sets (as a multiset of frozensets)
    from collections import Counter
    c_counter = Counter(corpus_sets)
    m_counter = Counter(model_sets)

    return c_counter == m_counter

