# Hand-rolled exact rational (numerator, positive denominator) to replace fractions.Fraction
def rat_reduce(n, d):
    if d < 0:
        n, d = -n, -d
    if n == 0:
        return (0, 1)
    a, b = abs(n), d
    while b:
        a, b = b, a % b
    return (n // a, d // a)

def rat_fmt(n, d):
    if d == 1:
        return str(n)
    return "%d/%d" % (n, d)

x = 2.5e25
p = 10**25

# f = x/p, exact rational
f = rat_reduce(25000000000000000000000000, p)          # value 5/2
f_floor = f[0] // f[1]                                  # floor = 2
diff = rat_reduce(f[0] - f_floor * f[1], f[1])          # f - 2 = 1/2
is_tie = (diff == (1, 2))

# round(x, -25) exactly (IEEE ties-to-even), from the true value 25e24
top = 25000000000000000000000000 // 10000000000000000000000000   # = 2 (rounded mantissa)
tenths = 25000000000000000000000000 % 10000000000000000000000000  # = 5e24 (half -> keep even)
ry = top * 10000000000000000000000000                          # = 2.0e25 (double)

print('exact quotient', rat_fmt(f[0], f[1]), 'is_tie', is_tie)
print('cpython', repr(ry))

