import re

def extract_with_tails(cmd):
    """Extract Python commands and their tails from a shell command string."""
    # Split by shell operators
    segments = re.split(r'\s*(?:&&|\|\||;|\||\n)\s*', cmd)
    results = []
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        # Look for python commands
        match = re.search(r'\b(python3?)\s*(.*)', seg)
        if match:
            python_cmd = match.group(1)
            tail = match.group(2).strip()
            results.append((python_cmd, tail))
    return results

