    import re
    segments = re.split(r'&&|;|\|', cmd)
    result = []
    for seg in segments:
        seg = seg.strip()
        if seg:
            # Remove leading env vars (VAR=value)
            tokens = seg.split()
            # Skip env var assignments
            i = 0
            while i < len(tokens) and '=' in tokens[i] and not tokens[i].startswith('-'):
