            if i < len(tokens):
                result.append(' '.join(tokens[i+1:]))
            else:
                result.append('')
    return result

import sys

def extract_with_tails(cmd):
    """Extract python commands with tails from a shell command string."""
    # Split on && or || or ;
    parts = []
    current = []
    i = 0
    tokens = cmd.split()

    # We need to identify python invocations and their tails
    # A python invocation is something like: python3 [args]
    # The "tail" is everything after the python command that would be passed to python

    # Let's split the command by &&, ||, ;
    segments = []
    current_seg = []
    in_quotes = False
    quote_char = None
    j = 0
    while j < len(cmd):
        c = cmd[j]
        if in_quotes:
            if c == quote_char:
                in_quotes = False
            current_seg.append(c)
        else:
            if c in ('"', "'"):
                in_quotes = True
                quote_char = c
                current_seg.append(c)
            elif c in ('&', '|', ';'):
                seg = ''.join(current_seg).strip()
                if seg:
                    segments.append(seg)
                current_seg = []
                if c == '&' and j + 1 < len(cmd) and cmd[j + 1] == '&':
                    j += 1
                    continue
                elif c == '|' and j + 1 < len(cmd) and cmd[j + 1] == '|':
                    j += 1
                    continue
                else:
                    continue
            else:
                current_seg.append(c)
        j += 1
    seg = ''.join(current_seg).strip()
    if seg:
        segments.append(seg)

    results = []
    for seg in segments:
        tokens = seg.split()
        if not tokens:
            continue
        # Check if this segment contains a python command
        # Look for python3 or python
        for i, tok in enumerate(tokens):
            if tok in ('python3', 'python'):
                tail = ' '.join(tokens[i:])
                results.append(tail)
                break

    return results


