def _sqrt_pos(x):
    """Newton's method for positive x, starting from a good initial guess."""
    # Find an initial guess using bit manipulation for IEEE 754 doubles
    import struct
    def _ieee_to_bits(x):
        return struct.unpack('<Q', struct.pack('<d', x))[0]

    bits = _ieee_to_bits(x)
    # Set exponent to 1023 + (exp - 1023)/2
    # Mask for exponent (bits 52-62)
    exponent = (bits >> 52) & 0x7FF
    frac = bits & 0x000FFFFFFFFFFFFF
    new_exponent = (exponent - 1023) // 2 + 1023
    guess_bits = (new_exponent << 52) | (frac >> 1)
    initial_guess = struct.unpack('<d', struct.pack('<Q', guess_bits))[0]

    # Newton iteration
    if initial_guess == 0.0:
        return 0.0
    y = initial_guess
    for _ in range(100):
        new_y = 0.5 * (y + x / y)
        if new_y == y:
            break
        y = new_y
    return y

def _sqrt(v):
    if v < 0:
        raise ValueError("math domain error")
    if v == 0.0:
        return 0.0
    if v != v:  # NaN
        return float('nan')
    if v == float('inf'):
        return float('inf')
    if v == -float('inf'):
        raise ValueError("math domain error")
    return _sqrt_pos(v)

