def _widthprec(fmt):
    m = re.match(r'^%([ \+#-]*)(\d+)?((?:\.\d+)?)', fmt)
    flags = m.group(1) or ''
    width = int(m.group(2)) if m.group(2) is not None else None
    prec = int(m.group(3)[1:]) if m.group(3) else None
    return flags, width, prec

def do_convert(fmt, val):
    m = re.match(r'^%([ \+#-]*)(\d+)?((?:\.\d+)?)([diuxXocs])', fmt)
    flags, width, prec, conv = m.group(1), m.group(2), m.group(3), m.group(4)
    fp, fwidth, fprec = _widthprec(fmt)
    assert fp == flags and fwidth == (int(width) if width else None) and fprec == (int(prec[1:]) if prec else None)
    if conv == 's':
        s = (val if val is None else str(val))
        if fprec is not None:
            s = s[:fprec]
        if flags == '':
            return s
        body = s.ljust(fwidth) if fwidth is not None and len(s) < fwidth else s
        if flags[0] == '-':
            return body
        pad = ' '
        if fwidth is not None and len(body) < fwidth:
            body = pad * (fwidth - len(body)) + body
        return body
    # integer conversions (d,i,u,x,X,o,c)
    neg = val < 0
    if conv == 'd' or conv == 'i':
        raw = str(val)
    elif conv == 'u':
        raw = str(val)
    elif conv == 'x':
        raw = format(val, 'x')
    elif conv == 'X':
        raw = format(val, 'X')
    elif conv == 'o':
        raw = format(val, 'o')
    elif conv == 'c':
        raw = chr(val)
    else:
        raise ValueError('unreachable')
    if fprec is not None and conv != 'c':
        # precision = minimum number of digits for integer conversions
        if val == 0:
            core = '0' * fprec
        elif len(raw) < fprec:
            core = raw.rjust(fprec, '0')
        else:
            core = raw
    else:
        core = raw
    body = core
    if not neg and '+' in flags and conv in 'diuxXo':
        body = '+' + body
    elif neg and conv == 'u':
        body = '-' + core  # GCC-style: '-' followed by the magnitude
    if neg and conv not in 'c':
        body = '-' + body
    if fwidth is not None and len(body) < fwidth:
        if '0' in flags:
            pad = '0'
            if body[0] in '+-':
                body = body[0] + pad * (fwidth - len(body)) + body[1:]
            else:
                body = pad * (fwidth - len(body)) + body
        elif flags[0] == ' ':
            pad = ' '
            if body[0] in '+-':
                body = body[0] + pad * (fwidth - len(body)) + body[1:]
            else:
                body = pad * (fwidth - len(body)) + body
        elif flags[0] == '-':
            body = body.ljust(fwidth)
        else:
            body = ' ' * (fwidth - len(body)) + body
    return body

