def _resolve_format(fmt, value, for_d=False, is_minus=False):
    """
    Resolve a printf-style format string without using the % operator.
    We handle the specific cases we need:
    - %.2d, %.2i, %.2u: minimum digits for integer
    - %.2x, %.2X, %.2o: minimum digits for hex/oct
    - %.2c: single char
    - %.2s: max length 2 for string
    - %.0d: minimum digits 0
    - %.d: no precision (default)
    - %5.2d: width 5, precision 2
    - %-5.2d: left-aligned, width 5, precision 2
    - %05.2d: zero-padded, width 5, precision 2
    - %+.2d: sign, precision 2
    - %05.7d: zero-padded, width 5, precision 7
    """
    s = fmt

    # Check if it ends with 's' or 'c'
    if s.endswith('s'):
        # Handle string: %.2s means max length 2
        # Remove leading %
        body = s[1:]
        # Find where the 's' is
        idx = body.rfind('s')
        spec = body[:idx]
        # Parse spec
        # spec might contain flags, width, .precision
        # For strings: .precision is max length
        neg = spec.startswith('-')
        if neg:
            spec = spec[1:]
        if '.' in spec:
            precision = int(spec[spec.find('.')+1:])
        else:
            precision = None
        result = value[:precision] if precision is not None else value
        # Apply width if specified
        # Extract width: after removing flags and precision
        spec_no_prec = spec.split('.')[0]
        # Remove non-digit from end of spec_no_prec for width
        width_chars = ''
        for ch in reversed(spec_no_prec):
            if ch.isdigit():
                width_chars = ch + width_chars
            else:
                break
        width = int(width_chars) if width_chars else 0
        if width > 0:
            if neg:
                result = result.ljust(width)
            else:
                result = result.rjust(width)
        return result

    if s.endswith('c'):
        # Handle char: %.2c means the char (precision ignored for char)
        idx = s.rfind('c')
        spec = s[1:idx]
        # Convert value to char
        ch = chr(value)
        # Width handling
        neg = spec.startswith('-')
        if neg:
            spec = spec[1:]
        spec_no_prec = spec.split('.')[0]
        width_chars = ''
        for ch2 in reversed(spec_no_prec):
            if ch2.isdigit():
                width_chars = ch2 + width_chars
            else:
                break
        width = int(width_chars) if width_chars else 0
        if width > 0:
            if neg:
                ch = ch.ljust(width)
            else:
                ch = ch.rjust(width)
        return ch

    # Integer conversions: d, i, u, x, X, o
    # Parse the format
    body = s[1:]
    # Find the conversion specifier
    conv = body[-1]
    spec = body[:-1]

    # Determine sign
    is_signed = conv in ('d', 'i', 'o', 'x', 'X')  # u is unsigned
    show_plus = False
    if '+' in spec:
        show_plus = True
        spec = spec.replace('+', '')
    if '-' in spec:
        is_minus = True
        spec = spec.replace('-', '')
    if '0' in spec:
        zero_pad = True
        spec = spec.replace('0', '')
    else:
        zero_pad = False

    # Extract width and precision
    width = 0
    precision = None
    if '.' in spec:
        # Precision present
        parts = spec.split('.')
        spec_part = parts[0]
        precision = int(parts[1])
    else:
        spec_part = spec

    # Width is the trailing digits of spec_part
    width_chars = ''
    for ch in reversed(spec_part):
        if ch.isdigit():
            width_chars = ch + width_chars
        else:
            break
    if width_chars:
        width = int(width_chars)

    # Format the integer value
    if conv == 'x':
        formatted = format(value, 'x') if value >= 0 else format(value, 'x')  # for negative, we'll handle sign
        if value < 0:
            formatted = '-' + format(abs(value), 'x')
    elif conv == 'X':
        formatted = format(value, 'X') if value >= 0 else format(value, 'X')
        if value < 0:
            formatted = '-' + format(abs(value), 'X')
    elif conv == 'o':
        formatted = format(value, 'o') if value >= 0 else format(value, 'o')
        if value < 0:
            formatted = '-' + format(abs(value), 'o')
    else:
        # d, i, u
        formatted = str(abs(value)) if value < 0 else str(value)
        if value < 0:
            formatted = '-' + str(abs(value))
        elif show_plus:
            formatted = '+' + str(value)

    # Apply precision (minimum digits)
    if precision is not None and precision > 0:
        # Count sign
        sign_len = 0
        if formatted.startswith('-'):
            sign_len = 1
        elif formatted.startswith('+'):
            sign_len = 1
