def _recent_capture_note(log_path: str) -> str:
    """Return a string describing the most recent capture note if within the last 7 days,
    or a fallback message otherwise."""
    try:
        with open(log_path, "r") as f:
            lines = f.readlines()
    except (FileNotFoundError, OSError):
        return "no recent note"

    if not lines:
        return "no recent note"

    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = now - datetime.timedelta(days=7)

    most_recent = None
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            continue
        if entry.get("kind") != "note":
            continue
        ts_str = entry.get("ts")
        if not ts_str:
            continue
        try:
            ts = datetime.datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%S.%fZ")
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
        if ts >= cutoff:
            if most_recent is None or ts > most_recent[0]:
                most_recent = (ts, entry.get("detail", ""))

    if most_recent is None:
        return "no recent note"
    return most_recent[1]


