import json, tempfile, datetime, pathlib, os

def _recent_capture_note(path: str) -> str:
    """Return the detail of the most recent note entry in the JSONL file at path,
    if it was written within the last 24 hours, else an empty string."""
    if not os.path.exists(path):
        return ""
    try:
        with open(path, "r") as f:
            lines = f.readlines()
    except Exception:
        return ""

    newest = None
    newest_ts = None
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if obj.get("kind") != "note":
            continue
        ts_str = obj.get("ts", "")
        try:
            # Parse ISO format like "2024-01-01T12:00:00.000Z"
            ts_str_clean = ts_str.replace("Z", "+00:00")
            ts = datetime.datetime.fromisoformat(ts_str_clean)
        except Exception:
            continue
        if newest_ts is None or ts > newest_ts:
            newest_ts = ts
            newest = obj

    if newest is None:
        return ""

    now = datetime.datetime.now(datetime.timezone.utc)
    age = now - newest_ts
    if age <= datetime.timedelta(hours=24):
        return newest.get("detail", "")
    return ""

