def _cmp_sort_key(k):
    if isinstance(k, bool):
        return (1, int(k))
    if isinstance(k, int):
        return (0, k)
    if isinstance(k, float):
        return (2, k)
    if isinstance(k, str):
        return (3, k)
    return (4, repr(k))

def sorted_set(s):
    return sorted(s, key=_cmp_sort_key)

