def list_sort_key(x):
    if isinstance(x, bool):
        return (2 if x else 1, 0, 0)
    if isinstance(x, int):
        return (0, x, 0)
    if isinstance(x, float):
        return (1, x, 0)
    return (3, repr(x), 0)

