def custom_repr(s):
    if not s:
        return "''"

    has_single = "'" in s
    has_double = '"' in s

    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    out = []
    for c in s:
        if c == quote:
            out.append('\\' + quote)
        elif c == '\\':
            out.append('\\\\')
        elif c == '\n':
            out.append('\\n')
        elif c == '\t':
            out.append('\\t')
        elif c == '\r':
            out.append('\\r')
        elif 32 <= ord(c) < 127:
            out.append(c)
        else:
            out.append('\\u%04x' % ord(c))

    return quote + ''.join(out) + quote

