def custom_repr_str(s):
    # Mimic Python's repr() for strings
    if not s:
        return "''"

    # Check if we can use single quotes
    if "'" not in s and "\n" not in s and "\t" not in s and "\\" not in s:
        # No need for backslash escapes except for the quotes themselves
        # But we need to check for non-printable or non-ascii
        single_ok = True
        for c in s:
            if c == "\n" or c == "\t" or c == "\\" or c == "\r":
                single_ok = False
                break
            if ord(c) < 32 or ord(c) >= 127:
                single_ok = False
                break
        if single_ok:
            return "'" + s + "'"

    # Use double quotes
    double_ok = True
    for c in s:
        if c == '"' or c == "\n" or c == "\t" or c == "\\" or c == "\r":
            double_ok = False
            break
        if ord(c) < 32 or ord(c) >= 127:
            double_ok = False
            break

    if double_ok:
        return '"' + s + '"'

    # Need escapes. Use double quotes as default when special chars present
    # Actually, Python chooses based on which quote is present
    # Simplified: use double quotes and escape everything
    out = ['"']
    for c in s:
        o = ord(c)
        if c == '\\':
            out.append('\\\\')
        elif c == '"':
            out.append('\\"')
        elif c == '\n':
            out.append('\\n')
        elif c == '\t':
            out.append('\\t')
        elif c == '\r':
            out.append('\\r')
        elif o < 32:
            out.append('\\x' + format(o, '02x'))
        elif o < 128:
            out.append(c)
        else:
            # Non-ASCII: Python uses \uXXXX for codepoints < 0x10000, \UXXXXXXXX for higher
            if o <= 0xFFFF:
                out.append('\\u' + format(o, '04x'))
            else:
                out.append('\\U' + format(o, '08x'))
    out.append('"')
    return ''.join(out)

