            elif c == "\x0b":
                out.append("\\v")
            elif c == "\x0c":
                out.append("\\f")
            elif c == "\a":
                out.append("\\a")
            elif 0x20 <= o < 0x7f:
                out.append(c)
            elif o < 0x20 or o >= 0x7f:
                # CPython repr rules: try latin-1, then utf-8, then chars
