                        out.append('\\\\' + b.hex().upper())
                    except UnicodeEncodeError:
                        out.append('\\u' + format(o, '04x').upper())
        else:
            if c == "'":
                out.append("\\'")
            elif c == "\\":
                out.append("\\\\")
            elif c == "\n":
                out.append("\\n")
            elif c == "\t":
                out.append("\\t")
            elif c == "\r":
