import unicodedata


def repr_u(s):
    out = ['"']
    for ch in s:
        code = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\0':
            out.append('\\0')
        elif ch == '\v':
            out.append('\\v')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\b':
            out.append('\\b')
        elif code < 0x20 or code >= 0x7f:
            name = unicodedata.name(ch, None)
            if name:
                out.append('\\N{')
                for nc in name:
                    if nc in '()}':
                        out.append('\\')
                    out.append(nc)
                out.append('}')
            else:
                out.append('\\x{:02x}'.format(code))
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)


