def char_repr(c):
    # Compute what repr() would produce for a single non-ASCII character
    # without calling repr() itself.
    cp = ord(c)
    if 32 <= cp <= 126:
        # Printable ASCII - repr would return the character as-is
        return c
    elif cp == 10:
        return "\\n"
    elif cp == 9:
        return "\\t"
    elif cp == 13:
        return "\\r"
    else:
        # For non-printable or non-ASCII, repr uses \uXXXX format
        return "\\u%04x" % cp

def string_repr(s):
    # Build the repr of the string s without calling repr()
    # Use single quotes for the outer delimiters
    parts = []
    for c in s:
        cp = ord(c)
        if cp == 39:  # single quote
            parts.append("\\'")
        elif cp == 92:  # backslash
            parts.append("\\\\")
        elif 32 <= cp <= 126:
            parts.append(c)
        elif cp == 10:
            parts.append("\\n")
        elif cp == 9:
            parts.append("\\t")
        elif cp == 13:
            parts.append("\\r")
        else:
            parts.append("\\u%04x" % cp)
    return "'" + "".join(parts) + "'"

