def make_repr(s):
    if s == "":
        return "''"
    start_quote = "'"
    end_quote = "'"
    if "'" in s and '"' not in s:
        start_quote = '"'
        end_quote = '"'
    body = ""
    for c in s:
        o = ord(c)
        if c == "\\":
            body += "\\\\"
        elif start_quote == "'" and c == "'":
            body += "\\'"
        elif start_quote == '"' and c == '"':
            body += '\\"'
        elif c == "\n":
            body += "\\n"
        elif c == "\t":
            body += "\\t"
        elif c == "\r":
            body += "\\r"
        elif c == "\b":
            body += "\\b"
        elif c == "\f":
            body += "\\f"
        elif c == "\v":
            body += "\\v"
        elif o < 32 or o == 127:
            if o < 0x10:
                body += "\\x%02x" % o
            else:
                body += "\\x%02x" % o
        elif o > 126:
            # Non-ASCII: emit as \uXXXX or \UXXXXXXXX
            if o <= 0xffff:
                body += "\\u%04x" % o
            else:
                body += "\\U%08x" % o
        else:
            body += c
    return start_quote + body + end_quote

