def dataclass(cls=None, **kw):
    def decorator(c):
        fields = {}
        if '__dataclass_fields__' in c.__dict__:
            fields = dict(c.__dict__['__dataclass_fields__'])
        # Collect fields from annotations
        for k, v in list(c.__dict__.items()):
            if k.startswith('_'):
                continue
            if isinstance(v, _Field):
                fields[k] = v
            else:
                # Check if there's an annotation
                if hasattr(c, '__annotations__') and k in c.__annotations__:
                    fields[k] = _Field(default=v)

        # Build __init__
        field_names = []
        for k in c.__annotations__:
            if k not in c.__dict__ or isinstance(c.__dict__.get(k), _Field):
                field_names.append(k)
            elif hasattr(c, '__annotations__') and k in c.__annotations__:
                field_names.append(k)

        # Simpler: use __dataclass_fields__ pattern
        # We'll build a proper __init__
        init_fields = []
        for name in list(c.__annotations__.keys()):
            if name in fields:
                f = fields[name]
                init_fields.append((name, f))
            elif name in c.__dict__ and not name.startswith('_'):
                f = _Field(default=c.__dict__[name])
                fields[name] = f
                init_fields.append((name, f))

        def __init__(self, *args, **kwargs):
            for name, f in init_fields:
                if f.init:
                    if name in kwargs:
                        setattr(self, name, kwargs[name])
                    elif args:
                        setattr(self, name, args[0])
                        args = args[1:]
                    elif f.default_factory is not None:
                        setattr(self, name, f.default_factory())
                    elif f.default is not ...:
                        setattr(self, name, f.default)
                    else:
                        raise TypeError(f"missing required argument: {name}")

        c.__init__ = __init__
        c.__dataclass_fields__ = fields
        return c

    if cls is not None:
        return decorator(cls)
    return decorator

