import sys

class Entry:
    _rank_fields = ("id", "first_seen")
    def __init__(self, id, program, count, first_seen, model, stdin_sample=None):
        self.id = id
        self.program = program
        self.count = count
        self.first_seen = first_seen
        self.model = model
        self.stdin_sample = stdin_sample

    @classmethod
    def from_obj(cls, obj):
        return cls(
            id=obj.get("id"),
            program=obj.get("program"),
            count=obj.get("count"),
            first_seen=obj.get("first_seen"),
            model=obj.get("model"),
            stdin_sample=obj.get("stdin_sample"),
        )

    def to_obj(self):
        return {
            "id": self.id,
            "program": self.program,
            "count": self.count,
            "first_seen": self.first_seen,
            "model": self.model,
            "stdin_sample": self.stdin_sample,
        }

def _rank(entry):
    return tuple(getattr(entry, f) for f in Entry._rank_fields)

def merge(list_a, list_b):
    result_a = []
    for entry in list_a:
        result_a.append(entry)
    # merge: for each entry in list_b, if a match exists in result_a by id, merge
    for entry_b in list_b:
        found = None
        for entry_a in result_a:
            if entry_a.id == entry_b.id:
                found = entry_a
                break
        if found is None:
            result_a.append(entry_b)
        else:
            # merge: increment count, keep first model (from first list) or from whichever is first
            found.count += entry_b.count
            # model: keep the one from the first list if both have it, else use whichever
            if found.model is None:
                found.model = entry_b.model
            # first_seen: keep the earlier one
            if entry_b.first_seen is not None and (found.first_seen is None or entry_b.first_seen < found.first_seen):
                found.first_seen = entry_b.first_seen
            # program: keep the one from the first list
            if found.program is None:
                found.program = entry_b.program
    return result_a

