def _fmod(x, y):
    """Compute math.fmod(x, y) without importing math."""
    # fmod: remainder with the sign of the dividend, |r| < |y|
    if y == 0.0:
        raise ZeroDivisionError("fmod by zero")
    if x == 0.0:
        return x if x >= 0.0 or 1.0 / x > 0 else -0.0
    absx = abs(x)
    absy = abs(y)
    r = absx % absy
    # Adjust: fmod returns remainder with sign of dividend
    # absx % absy gives a value in [0, absy)
    # If x is negative, fmod should give negative remainder
    if x < 0:
        if r != 0.0:
            r = r - absy
        else:
            r = -0.0
    # If x is positive, r is already positive
    # But we need to be careful: if x > 0 and r == 0, result is 0.0 (positive)
    # The sign of result matches sign of x
    return r

def _floor(x):
    """Compute math.floor(x) returning a float without importing math."""
    # For finite x, floor can be computed using int()
    # But int() truncates toward zero, so we need to adjust
    try:
        ix = int(x)
    except OverflowError:
        # x is too large for int, but that's fine for our purposes
        # Actually, if x is inf or -inf, int() raises OverflowError
        if x > 0:
            return float('inf')
        else:
            return float('-inf')
    # For negative x, int(x) rounds toward zero, so floor might be less
    if x < 0 and float(ix) != x:
        return float(ix - 1)
    return float(ix)

def _copysign(x, y):
    """Compute math.copysign(x, y) without importing math."""
    # Returns x with the sign of y
    if y > 0:
        if x < 0:
            return -x
        return x
    else:
        # y is negative or -0.0
        if x > 0:
            return -x
        return x

def cpython_style(x, y):
    """The else-branch algorithm, run in Python, with NO is_finite guard."""
    mod = _fmod(x, y)
    div = (x - mod) / y
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div -= 1.0
    if div == 0.0:
        return _copysign(0.0, x / y)
    fd = _floor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

