def _copysign(z, x):
    import struct
    def sign(s):
        h = struct.unpack('h', struct.pack('h', s))[0]
        return 1 if (h >> 15) & 1 else 0
    def to_bytes(b):
        return struct.pack('d', b)
    def from_bytes(b):
        return struct.unpack('d', b)[0]
    sz = struct.unpack('d', struct.pack('d', z))[0]
    sx = struct.unpack('d', struct.pack('d', x))[0]
    # extract sign bit
    zz = struct.unpack('q', struct.pack('d', sz))[0]
    zx = struct.unpack('q', struct.pack('d', sx))[0]
    zsign = zz & (1 << 63)
    xsign = zx & (1 << 63)
    if zsign == xsign:
        return sz
    else:
        # flip sign
        new_val = zz | (1 << 63) if not zsign else zz & ~ (1 << 63)
        return struct.unpack('d', struct.pack('q', new_val))[0]

