# Pure float helper functions, accurate to IEEE 754 double precision

def _isnan(v):
    return v != v

def _isinf(v):
    return v == float('inf') or v == float('-inf')

def _floorf(v):
    """Return float(floor(v)), correctly rounding half-to-even for float representation."""
    if _isnan(v) or _isinf(v):
        return v
    # Convert to Fraction exactly
    fr = Fraction(v)
    fl = float(floor(fr))
    return fl

def _ffloor(v):
    if _isnan(v) or _isinf(v):
        return v
    fr = Fraction(v)
    fl = floor(fr)
    return float(fl)

def _fmodf(x, y):
    """Return math.fmod(x, y) accurately."""
    if _isnan(x) or _isnan(y) or _isinf(x) or _isinf(y):
        return float('nan')
    if y == 0.0:
        return float('nan')
    # fmod is x - floor(x/y) * y in floating-point; we do it with exact fraction arithmetic
    # to avoid accumulation of FP error
    fx = Fraction(x)
    fy = Fraction(y)
    q = floor(fx / fy)
    r = fx - q * fy
    if r == 0:
        # Sign of r matches x per IEEE fmod
        r = 0.0 if (x >= 0.0 or r == 0) else -0.0
    else:
        r = float(r)
    if r == 0.0:
        # Ensure sign matches x when x and r are both zero (same-sign case)
        r = 0.0 if (x >= 0.0) else -0.0
    return r

def _copysign(mag, sign):
    if mag == 0.0:
        return 0.0 if sign >= 0.0 else -0.0
    return mag if sign >= 0.0 else -mag

