def _split_args(s):
    # Parse a comma-separated argument list, respecting quotes and parentheses
    args = []
    cur = []
    depth = 0
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == "'":
            # Read a single-quoted string
            cur.append("'")
            i += 1
            while i < n:
                cur.append(s[i])
                if s[i] == '\\':
                    if i + 1 < n:
                        cur.append(s[i+1])
                        i += 2
                        continue
                elif s[i] == "'":
                    i += 1
                    break
                i += 1
        elif c == '(':
            depth += 1
            cur.append(c)
