    # Otherwise, treat as a string (shouldn't happen)
    return s

def _eval_string(s):
    # Evaluate a Python string literal (the contents between quotes)
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s):
            nxt = s[i+1]
            if nxt == 'n':
                result.append('\n')
                i += 2
            elif nxt == 't':
                result.append('\t')
                i += 2
            elif nxt == 'r':
                result.append('\r')
                i += 2
            elif nxt == '0':
                result.append('\0')
                i += 2
            elif nxt == 'x':
                hex_str = s[i+2:i+4]
                result.append(chr(int(hex_str, 16)))
                i += 4
            elif nxt == '\\':
                result.append('\\')
                i += 2
            elif nxt == "'":
                result.append("'")
                i += 2
            else:
                # For cases like \1, \2, \8, etc. - keep the backslash and the digit
                result.append('\\' + nxt)
                i += 2
        else:
            result.append(c)
            i += 1
    return ''.join(result)

def _make_lambda(param, body):
    # Create a lambda that takes param and evaluates body
    # body is like: m.group(0).upper()
    # We can handle specific patterns
    if body == 'm.group(0).upper()':
        def lam(m):
            return m.group(0).upper()
        return lam
    raise ValueError("Unsupported lambda body: %s" % body)

