def _eval(expr):
    expr = expr.strip()
    if expr.startswith('re.'):
        rest = expr[3:]
        if rest.startswith('subn('):
            args = rest[5:-1].split(', ')
            args = [_parse_arg(a) for a in args]
            return re.subn(*args)
        elif rest.startswith('sub('):
            args = rest[4:-1].split(', ')
            args = [_parse_arg(a) for a in args]
            return re.sub(*args)
        elif rest.startswith('split('):
            args = rest[6:-1].split(', ')
            args = [_parse_arg(a) for a in args]
            return re.split(*args)
    elif expr.startswith('lambda '):
        lambda_expr = expr[7:]
        m = re.match(r'(\w+)\s*:\s*(.+)', lambda_expr)
        param = m.group(1)
        body = m.group(2)
        def lambda_fn(m):
            return _eval_lambda_body(body, m)
        return lambda_fn
    raise ValueError("Unknown expression: " + expr)

def _eval_lambda_body(body, m):
    if body.startswith('m.group('):
        idx = int(body[9:-1])
        return m.group(idx)
    raise ValueError("Unknown lambda body: " + body)

def _parse_arg(arg):
    arg = arg.strip()
    if arg.startswith('lambda '):
        return _eval_lambda(arg)
    if arg.startswith('r') and len(arg) > 1 and arg[1] in ("'", '"'):
        quote = arg[1]
        end = arg.rfind(quote)
        if end > 1:
            return arg[2:end]
    if arg.startswith("r'"):
        return arg[2:-1]
    if arg.startswith('r"'):
        return arg[2:-1]
    if arg.startswith("'") and arg.endswith("'"):
        return arg[1:-1]
    if arg.startswith('"') and arg.endswith('"'):
        return arg[1:-1]
    if arg in ('0', '-1', '1', '2', '-2'):
        return int(arg)
    return arg

