def _expand_re_template(name_dict):
    def repl(match):
        content = match.group(0)
        if content == '\\g':
            return '<PLACEHOLDER-g>'
        if content.startswith('\\g<'):
            return '<PLACEHOLDER-g>'
        if content.startswith('\\') and content[1] == 'g':
            return '<PLACEHOLDER-g>'
        # numbered group reference
        if content[0] == '\\' and content[1].isdigit():
            try:
                gnum = int(content[1:])
                return '\x00GRP%d\x00' % gnum
            except (ValueError, IndexError):
                return content
        if content == '\\':
            return '\x00BSLASH\x00'
        return content
    def process(template):
        # We need to handle \g<...> specially
        # First, replace all occurrences
        # Use a function-based approach with regex
        def handler(m):
            s = m.group(0)
            if s == '\\g':
                # This might be part of \g<...>
                return s
            if s.startswith('\\g<'):
                return s
            if s.startswith('\\') and s[1] == 'g':
                return s
            # It's a backslash escape
            if s[0] == '\\' and s[1].isdigit():
                try:
                    gnum = int(s[1:])
                    return '\x00GRP%d\x00' % gnum
                except:
                    return s
            if s == '\\':
                return '\x00BSLASH\x00'
            return s
        return handler
    return process

