def _eval_bytes_literal(s):
    s = s.strip()
    if s.startswith("b'"):
        inner = s[2:-1]
        # Handle escapes
        return _decode_escapes(inner, is_bytes=True)
    elif s.startswith('b"'):
        inner = s[2:-1]
        return _decode_escapes(inner, is_bytes=True)
    return b''

def _decode_escapes(s, is_bytes=False):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            c = s[i+1]
            if c == 'n':
                result.append('\n' if not is_bytes else b'\n')
            elif c == 't':
                result.append('\t' if not is_bytes else b'\t')
            elif c == 'r':
                result.append('\r' if not is_bytes else b'\r')
            elif c == '0':
                result.append('\0' if not is_bytes else b'\0')
            elif c == '\\':
                result.append('\\' if not is_bytes else b'\\')
            elif c == 'x' and i + 3 < len(s):
                hex_val = s[i+2:i+4]
                result.append(chr(int(hex_val, 16)) if not is_bytes else bytes([int(hex_val, 16)]))
                i += 3
                continue
            elif c.isdigit():
                # Octal
                oct_str = ''
                j = i + 1
                while j < len(s) and j < i + 4 and s[j].isdigit() and int(s[j]) < 8:
                    oct_str += s[j]
                    j += 1
                result.append(chr(int(oct_str, 8)) if not is_bytes else bytes([int(oct_str, 8)]))
                i = j - 1
                continue
            else:
                result.append(c)
            i += 2
        else:
            result.append(s[i])
            i += 1
    if is_bytes:
        if result and isinstance(result[0], bytes):
            return b''.join(result)
        return bytes(result)
    if result and isinstance(result[0], bytes):
        return ''.join(r if isinstance(r, str) else chr(r) for r in result)
    return ''.join(result)

