def _safe_eval(expr):
    # We only need to eval expressions of the form:
    # re.sub(...), re.subn(...), re.split(...)
    # with string, int, lambda arguments.
    import ast
    import types
    import operator

    allowed_names = {
        're': re,
        'True': True,
        'False': False,
        'None': None,
    }

    def eval_node(node, localns):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in allowed_names:
                return allowed_names[node.id]
            elif node.id in localns:
                return localns[node.id]
            else:
                raise NameError("name '%s' is not defined" % node.id)
        elif isinstance(node, ast.Call):
            func = eval_node(node.func, localns)
            args = []
            for arg in node.args:
                args.append(eval_node(arg, localns))
            kwargs = {}
            for kw in node.keywords:
                k = kw.arg
                v = eval_node(kw.value, localns)
                kwargs[k] = v
            return func(*args, **kwargs)
        elif isinstance(node, ast.Attribute):
            base = eval_node(node.value, localns)
            return getattr(base, node.attr)
        elif isinstance(node, ast.Lambda):
            def make_lambda(args, body):
                def lambda_func(*call_args, **call_kwargs):
                    local = {}
                    for i, arg in enumerate(args):
                        if i < len(call_args):
                            local[arg.arg] = call_args[i]
                        elif arg.arg in call_kwargs:
                            local[arg.arg] = call_kwargs[arg.arg]
                        else:
                            raise TypeError("missing required argument '%s'" % arg.arg)
                    return eval_node(body, local)
                return lambda_func
            return make_lambda(node.args.args, node.body)
        else:
            raise TypeError("unsupported node type: %s" % type(node).__name__)

    try:
        tree = ast.parse(expr, mode='eval')
        return eval_node(tree.body, {})
    except SyntaxError as e:
        raise NameError(e.msg)

