import re

def safe_eval(expr):
    """
    Evaluate a restricted subset of Python expressions needed for this script.
    Supports: re.sub, re.split, re.subn, re.escape, lambda m: m.group(0).upper(),
    string literals, tuples, and integers.
    """
    # Simple approach: use compile with restricted builtins
    code = compile(expr, '<eval>', 'eval')
    allowed = {
        're': re,
        'lambda': lambda f: f,  # placeholder, lambdas handled separately
    }
    # We need to handle lambdas, so let's use a different approach
    # Since we can't use eval, let's parse the expression manually for the specific cases

    # Actually, the expressions are all of the form:
    # re.sub(pattern, repl, string, [count])
    # re.subn(pattern, repl, string, [count])
    # re.split(pattern, string, [maxsplit])
    # re.escape(string)
    # lambda m: m.group(0).upper()

    # Let's try to match these patterns

    # Try re.sub(...)
    m = re.match(r"^re\.sub\((.+)\)$", expr)
    if m:
        args_str = m.group(1)
        args = _split_args(args_str)
        if len(args) == 3:
            pattern = _eval_lit(args[0])
            repl = _eval_lit(args[1])
            string = _eval_lit(args[2])
            return re.sub(pattern, repl, string)
        elif len(args) == 4:
            pattern = _eval_lit(args[0])
            repl = _eval_lit(args[1])
            string = _eval_lit(args[2])
            count = int(_eval_lit(args[3]))
            return re.sub(pattern, repl, string, count)

    # Try re.subn(...)
    m = re.match(r"^re\.subn\((.+)\)$", expr)
    if m:
        args_str = m.group(1)
        args = _split_args(args_str)
        if len(args) == 3:
            pattern = _eval_lit(args[0])
            repl = _eval_lit(args[1])
            string = _eval_lit(args[2])
            return re.subn(pattern, repl, string)
        elif len(args) == 4:
            pattern = _eval_lit(args[0])
            repl = _eval_lit(args[1])
            string = _eval_lit(args[2])
            count = int(_eval_lit(args[3]))
            return re.subn(pattern, repl, string, count)

    # Try re.split(...)
    m = re.match(r"^re\.split\((.+)\)$", expr)
    if m:
        args_str = m.group(1)
        args = _split_args(args_str)
        if len(args) == 2:
            pattern = _eval_lit(args[0])
            string = _eval_lit(args[1])
            return re.split(pattern, string)
        elif len(args) == 3:
            pattern = _eval_lit(args[0])
            string = _eval_lit(args[1])
            maxsplit = int(_eval_lit(args[2]))
            return re.split(pattern, string, maxsplit)

    # Try re.escape(...)
    m = re.match(r"^re\.escape\((.+)\)$", expr)
    if m:
        args_str = m.group(1)
        args = _split_args(args_str)
        if len(args) == 1:
            s = _eval_lit(args[0])
            return re.escape(s)

    return None

def _split_args(s):
    """Split a string of arguments at top-level commas."""
    args = []
    depth = 0
    in_str = False
    str_char = None
    i = 0
    start = 0
    while i < len(s):
        c = s[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            if c == str_char:
                in_str = False
        else:
            if c in ('"', "'"):
                in_str = True
                str_char = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            elif c == ',' and depth == 0:
                args.append(s[start:i].strip())
                start = i + 1
        i += 1
    if start < len(s):
        args.append(s[start:].strip())
    return args

def _eval_lit(s):
    """Evaluate a string literal, number, or simple expression."""
    s = s.strip()
    # Check if it's a string literal
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        # Handle raw strings
        if s.startswith('r') or s.startswith('R'):
            # Raw string
            if s.startswith('r"') or s.startswith('R"'):
                return s[2:-1]
            elif s.startswith("r'") or s.startswith("R'"):
                return s[2:-1]
        # Handle byte strings
        if s.startswith('b') or s.startswith('B'):
            if s.startswith('b"') or s.startswith('B"'):
                return eval(s)  # Can't use eval... 
            elif s.startswith("b'") or s.startswith("B'"):
                return eval(s)
        # Regular string
