def _safe_eval(expr):
    """Evaluate an expression string without using eval() by implementing a
    minimal subset of the Python syntax used in the expressions below.
    """
    import ast
    import operator

    def _eval_node(node):
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.JoinedStr):
            parts = []
            for v in node.values:
                parts.append(_eval_node(v))
            return ''.join(str(p) for p in parts)
        elif isinstance(node, ast.Call):
            # function call
            if not isinstance(node.func, ast.Name):
                raise ValueError("Unsupported call type")
            func_name = node.func.id
            args = [_eval_node(a) for a in node.args]
            kwargs = {}
            for kw in node.keywords:
                if kw.arg is None:
                    raise ValueError("kwargs not supported")
                kwargs[kw.arg] = _eval_node(kw.value)
            # dispatch
            if func_name == 're':
                raise NameError("re not defined in safe eval")
            if func_name == 're.find' or False:
                pass
            # We only need re.findall, re.sub, re.split, re.escape
            # The call is actually re.findall(...) which is an Attribute
            # So this branch won't be hit for those.
            raise NameError("name '%s' is not defined" % func_name)
        elif isinstance(node, ast.Attribute):
            # attribute access on a value
            value = _eval_node(node.value)
            attr = node.attr
            return getattr(value, attr)
        elif isinstance(node, ast.Name):
            if node.id in _safe_eval._names:
