def _is_valid_b64(s, validate):
    # s is a bytes-like object (bytes, bytearray, memoryview)
    data = bytes(s)
    if validate:
        allowed = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for c in data:
            if c == 0x0A or c == 0x0D:  # \n or \r
                continue
            if c not in allowed:
                return False
    # Check padding structure
    if data and data[0] == 0x3D:  # first char is '='
        return False
    n = len(data)
    if n == 0:
        return True
    # Count trailing '='
    eq_count = 0
    for i in range(n - 1, -1, -1):
        if data[i] == 0x3D:
            eq_count += 1
        else:
            break
    if eq_count == 0:
        return True
    if eq_count == 1:
        # invalid padding
        return False
    if eq_count == 2:
        # valid, total length should be 4
        return n == 4
    if eq_count == 3:
        # invalid: '====' or more
        return False
    return True

def _b64decode(data, validate=False, urlsafe=False):
    # Handle str
    if isinstance(data, str):
        data = data.encode('ascii')
    elif isinstance(data, (int, float)):
        raise TypeError("Expected bytes, bytearray or str, got %s" % type(data).__name__)

    # Convert to bytes for processing
    if isinstance(data, memoryview):
        raw = bytes(data)
    else:
        raw = data

    # Check if there are non-base64 chars
    # Determine padding validity
    if not _is_valid_b64(raw, validate):
        raise Exception("binascii.Error: Incorrect padding")

    # Now do the actual decoding
    if urlsafe:
        # Convert URL-safe chars to standard
        s = raw.replace(b'-', b'+').replace(b'_', b'/')
    else:
        s = raw

    # Build decode table
    table = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

    # Remove whitespace
    filtered = bytes(c for c in s if c not in (0x0A, 0x0D, 0x20, 0x09, 0x0B, 0x0C))

    # If there are non-base64 chars (and not validate mode, we still need to handle)
    # Actually, in non-validate mode, CPython's base64.b64decode ignores non-base64 chars
    # Let me re-check: b64decode without validate ignores non-alphabet characters

    if not urlsafe:
        # For non-urlsafe, the default b64decode ignores non-base64 chars
        # Let me filter them out
        filtered = bytes(c for c in s if c in table or c == 0x3D)
    else:
        # urlsafe_b64decode also ignores non-base64 chars after conversion
        filtered = bytes(c for c in s if c in table or c == 0x3D)

    # Now decode
    n = len(filtered)
    result = bytearray()
    i = 0
    while i < n:
        # Get 4 chars (or fewer at end)
        chunk = []
        for j in range(4):
            if i + j < n:
                chunk.append(filtered[i + j])
            else:
                chunk.append(0)  # pad
        # Now we have 4 bytes
        vals = []
        for c in chunk:
            if c == 0x3D:
                vals.append(None)
            else:
                idx = table.find(bytes([c]))
                if idx == -1:
                    raise Exception("binascii.Error: Non-base64 digit found")
                vals.append(idx)
        # Decode
        if vals[0] is None:
            break
        b0 = vals[0] << 2
        if vals[1] is not None:
            b0 |= vals[1] >> 4
            result.append(b0 & 0xFF)
            if vals[2] is not None:
                b1 = (vals[1] & 0x0F) << 4
                b1 |= vals[2] >> 2
                result.append(b1 & 0xFF)
                if vals[3] is not None:
                    b2 = (vals[2] & 0x03) << 6
                    b2 |= vals[3]
                    result.append(b2 & 0xFF)
        i += 4
    return bytes(result)

def _b64encode(data, altchars=None):
    if isinstance(data, str):
        data = data.encode('ascii')
    elif isinstance(data, (int, float)):
        raise TypeError("Expected bytes, bytearray or str, got %s" % type(data).__name__)
    if isinstance(data, memoryview):
        data = bytes(data)

    table = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    if altchars is not None:
        if isinstance(altchars, str):
            altchars = altchars.encode('ascii')
        table = table[:-2] + altchars

    n = len(data)
    result = bytearray()
    i = 0
    while i < n:
        remaining = n - i
        if remaining >= 3:
            b0, b1, b2 = data[i], data[i+1], data[i+2]
            c0 = b0 >> 2
            c1 = ((b0 & 3) << 4) | (b1 >> 4)
            c2 = ((b1 & 15) << 2) | (b2 >> 6)
            c3 = b2 & 63
            result.extend([table[c0], table[c1], table[c2], table[c3]])
        elif remaining == 2:
            b0, b1 = data[i], data[i+1]
            c0 = b0 >> 2
            c1 = ((b0 & 3) << 4) | (b1 >> 4)
            c2 = (b1 & 15) << 2
            result.extend([table[c0], table[c1], table[c2], 0x3D])
        else:
            b0 = data[i]
            c0 = b0 >> 2
            c1 = (b0 & 3) << 4
            result.extend([table[c0], table[c1], 0x3D, 0x3D])
        i += 3
    return bytes(result)

def b64decode(s, altchars=None, validate=False):
    if isinstance(s, str):
        s = s.encode('ascii')
    return _b64decode(s, validate=validate, urlsafe=False)

def urlsafe_b64decode(s):
    if isinstance(s, str):
