    data = bytes(s)
    stripped = b''.join(ch for ch in data if ch != 0x0A and ch != 0x0D)
    if validate:
        for b in stripped:
            if b not in table:
                raise ValueError(b"Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4" % len(stripped))
