        if d2 is None or d3 is None:
            d2 = 0; d3 = 0
        out.append((d0 << 2) | (d1 >> 4))
        if d2 is not None or d3 is not None:
            out.append(((d1 & 0x0F) << 4) | (d2 >> 2))
        if d3 is not None:
            out.append(((d2 & 0x03) << 6) | d3)
        i += 4
    r = n - i
    if r == 0:
        pass
    elif r == 1:
        raise ValueError(b"Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4" % n)
    elif r == 2:
        d0 = table.get(stripped[i]); d1 = table.get(stripped[i+1])
        if d0 is None or d1 is None:
            raise ValueError(b"Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4" % n)
        out.append((d0 << 2) | (d1 >> 4))
    elif r == 3:
        d0 = table.get(stripped[i]); d1 = table.get(stripped[i+1]); d2 = table.get(stripped[i+2])
        if d0 is None or d1 is None:
            raise ValueError(b"Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4" % n)
