def b64encode(s, altchars=None):
    if isinstance(s, str):
        s = s.encode('utf-8')
    elif isinstance(s, (bytearray, memoryview)):
        s = bytes(s)
    if not isinstance(s, bytes):
        raise TypeError("argument should be a bytes-like object or ASCII string, not %r" % type(s).__name__)

    # Standard base64 encoding
    if len(s) == 0:
        encoded = b""
    elif len(s) % 3 == 0:
        encoded = binascii.b2a_base64(s).rstrip(b'\n')
    elif len(s) % 3 == 1:
        encoded = binascii.b2a_base64(s).rstrip(b'\n')[:-1] + b"=="
    else:
        encoded = binascii.b2a_base64(s).rstrip(b'\n')[:-1] + b"="

    if altchars is not None:
        altchars = bytes(altchars) if isinstance(altchars, str) else altchars
        if len(altchars) != 2:
            raise ValueError("altchars must have length 2")
        encoded = encoded.replace(b'+', bytes([altchars[0]])).replace(b'/', bytes([altchars[1]]))
    return encoded


def b64decode(s, altchars=None, validate=False):
    if isinstance(s, str):
        s = s.encode('utf-8')
    elif isinstance(s, (bytearray, memoryview)):
        s = bytes(s)
    if not isinstance(s, bytes):
        raise TypeError("argument should be a bytes-like object or ASCII string, not %r" % type(s).__name__)

    # Handle newlines
    s = s.replace(b'\n', b'').replace(b'\r', b'')

    if altchars is not None:
        altchars = bytes(altchars) if isinstance(altchars, str) else altchars
        if len(altchars) != 2:
            raise ValueError("altchars must have length 2")
        s = s.replace(bytes([altchars[0]]), b'+').replace(bytes([altchars[1]]), b'/')

    # Validate if needed
    if validate:
        # Check for invalid characters
        valid = b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/='
        for i, c in enumerate(s):
            if c not in valid:
                raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % (len(s),))

    # Check padding
    padding = 0
    for c in reversed(s):
        if c == b'=':
            padding += 1
        else:
            break

    if padding > 2:
        raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % (len(s),))

    # Check for '=' in the middle
    stripped = s.rstrip(b'=')
    if b'=' in stripped:
        raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % (len(s),))

    # Decode
    try:
        if padding == 0:
            result = binascii.a2b_base64(s)
        elif padding == 1:
            result = binascii.a2b_base64(s)
        elif padding == 2:
            result = binascii.a2b_base64(s)
        else:
            result = binascii.a2b_base64(s)
    except binascii.Error as e:
        raise binascii.Error(str(e))

    return result


