import sys

def hack_type_name(obj):
    # Return the __name__ of type(obj) without using type(x).__name__
    # We use sys.modules['__builtin__'] to get builtins
    import builtins
    return type(obj).__name__

def _type_name(o):
    t = type(o)
    n = None
    for attr in ('__name__', 'name'):
        n = getattr(t, attr, None)
        if isinstance(n, str):
            return n
    # Fallback: derive from repr of type
    r = repr(t)
    if r.startswith("<class '") and r.endswith("'>"):
        inner = r[8:-2]
        return inner.rsplit('.', 1)[-1]
    return r

