# Unwrap nested frozensets to simple sets for hashing
def _unpack(f):
    if isinstance(f, frozenset) and len(f) == 1:
        inner = next(iter(f))
        if isinstance(inner, frozenset) and len(inner) == 1:
            return inner
        if isinstance(inner, frozenset):
            return {x for x in _unpack(fs) for fs in inner}
        return {inner}
    return f

def _canon(fro):
    return frozenset(sorted(_unpack(fro)))

