def safe_repr(o):
    try:
        return repr(o)
    except Exception:
        pass
    # Fallback: manually construct repr for dict views
    if isinstance(o, dict):
        items = []
        for k, v in o.items():
            items.append('%r: %r' % (k, v))
        return '{%s}' % ', '.join(items)
    # For other objects, try to format as list of (key, value)
    if hasattr(o, '__iter__'):
        try:
            items = []
            for it in o:
                if isinstance(it, tuple) and len(it) == 2:
                    items.append('%r: %r' % (it[0], it[1]))
                else:
                    items.append(repr(it))
            return '[%s]' % ', '.join(items)
        except Exception:
            pass
    # Last resort: show type and try to get some representation
    try:
        type_name = type(o).__name__
        try:
            items = []
            for it in o:
                items.append(repr(it))
            return '%s(%s)' % (type_name, ', '.join(items))
        except Exception:
            return '<unrepresentable %s>' % type_name
    except Exception:
        return '<unrepresentable>'

def safe_iter(o):
    try:
        return iter(o)
    except Exception:
        return None

