import os
import sys

# CSV constants
QUOTE_MINIMAL = 0
QUOTE_ALL = 1
QUOTE_NONNUMERIC = 2
QUOTE_NONE = 3

class CSVWriter:
    def __init__(self, write_func, quoting=QUOTE_MINIMAL, escapechar=None, 
                 doublequote=True, delimiter=',', quotechar='"', lineterminator='\r\n'):
        # Validate parameters
        if not isinstance(delimiter, str) or len(delimiter) != 1:
            raise TypeError("delimiter must be a 1-character string")
        if quoting not in (0, 1, 2, 3):
            raise ValueError("quoting must be an int in (0,1,2,3)")  # Actually it checks for the enum values
        if escapechar is not None:
            if not isinstance(escapechar, str) or len(escapechar) != 1:
                raise TypeError("escapechar must be a 1-character string")
        if quotechar is not None:
            if not isinstance(quotechar, str) or len(quotechar) != 1:
                raise TypeError("quotechar must be a 1-character string")
        if lineterminator is not None and not isinstance(lineterminator, str):
            raise TypeError("lineterminator must be a string")

        self.write_func = write_func
        self.quoting = quoting
        self.escapechar = escapechar
        self.doublequote = doublequote
        self.delimiter = delimiter
        self.quotechar = quotechar
        self.lineterminator = lineterminator

    def writerow(self, row):
        parts = []
        for field in row:
            parts.append(self._format_field(field))
        line = self.delimiter.join(parts) + self.lineterminator
        self.write_func(line)
        return len(line.encode('utf-8'))

    def _format_field(self, field):
        # Convert to string if not already
        if isinstance(field, bytes):
            s = field.decode('utf-8')
        elif isinstance(field, bool):
            s = 'True' if field else 'False'
        elif field is None:
            s = ''
        elif isinstance(field, float):
            s = repr(field)
        elif isinstance(field, int):
            s = str(field)
        else:
            s = str(field)

        needs_quote = False
        if self.quoting == QUOTE_ALL:
            needs_quote = True
        elif self.quoting == QUOTE_NONNUMERIC:
            # Quote if not a number - but we've already converted to string
            # The original value matters here
            if isinstance(field, str):
                needs_quote = True
        elif self.quoting == QUOTE_NONE:
            pass  # No quoting
        else:  # QUOTE_MINIMAL
            if (self.delimiter and self.delimiter in s or
                self.quotechar and self.quotechar in s or
                '\r' in s or '\n' in s):
                needs_quote = True

        if not needs_quote:
            return s

        if self.quotechar is None:
            # Can't quote, just return as-is (or raise?)
            return s

        # Need to escape the content
        result = []
        result.append(self.quotechar)
        for ch in s:
            if ch == self.quotechar:
                if self.doublequote:
                    result.append(self.quotechar * 2)
                elif self.escapechar:
                    result.append(self.escapechar)
                    result.append(ch)
                else:
                    # Can't escape properly
                    result.append(ch)
            elif ch == self.escapechar and self.escapechar is not None:
                if self.escapechar is not None:
                    result.append(self.escapechar * 2)
                else:
                    result.append(ch)
            else:
                result.append(ch)
        result.append(self.quotechar)
        return ''.join(result)

